   288	static void display_queue_companion_prompt(velawear_display_t *display,
   289	                                           const char *prompt)
   290	{
   291	  velawear_event_t event;
   292	  size_t length;
   293	  int ret;
   294	
   295	  if (display == NULL || display->events == NULL || prompt == NULL)
   296	    {
   297	      return;
   298	    }
   299	
   300	  length = strlen(prompt);
   301	  if (length == 0 || length >= sizeof(event.data.chat.text))
   302	    {
   303	      syslog(LOG_WARNING, "[HCI] Companion prompt length invalid: %lu\n",
   304	             (unsigned long)length);
   305	      return;
   306	    }
   307	
   308	  memset(&event, 0, sizeof(event));
   309	  event.type = VELAWEAR_EVENT_CHAT_INPUT;
   310	  event.priority = VELAWEAR_PRIORITY_HIGH;
   311	  event.timestamp = display_now_ms();
   312	  event.data.chat.length = (int)length;
   313	  memcpy(event.data.chat.text, prompt, length);
   314	  event.data.chat.text[length] = '\0';
   315	  ret = event_manager_push(display->events, &event);
   316	  if (ret < 0)
   317	    {
   318	      syslog(LOG_WARNING, "[HCI] Companion prompt queue failed: %d\n", ret);
   319	      return;
   320	    }
   321	
   322	  display_manager_set_companion_phase(display,
   323	                                        VELAWEAR_COMPANION_THINKING,
   324	                                        "我正在想怎么陪你...");
   325	  syslog(LOG_INFO, "[HCI] Companion quick prompt queued bytes=%lu\n",
   326	         (unsigned long)length);
