  1379	void display_manager_tick(velawear_display_t *display)
  1380	{
  1381	  uint32_t now;
  1382	  velawear_state_t state;
  1383	  lv_obj_t *alert_label;
  1384	
  1385	  if (display == NULL || !display->initialized)
  1386	    {
  1387	      return;
  1388	    }
  1389	
  1390	  now = display_now_ms();
  1391	  display_audio_poll(display);
  1392	  pthread_mutex_lock(&display->lock);
  1393	  if (display->alert_pending)
  1394	    {
  1395	      lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
  1396	      lv_label_set_text(display->status_label, "主动提醒");
  1397	      lv_obj_set_style_text_color(display->status_label,
  1398	                                  lv_color_hex(0xfca5a5), 0);
  1399	      alert_label = display->detail_active ? display->metrics_label :
  1400	                    display->page_content[0];
  1401	      if (alert_label != NULL)
  1402	        {
  1403	          lv_label_set_text(alert_label, display->pending_alert);
  1404	          lv_obj_set_style_text_color(alert_label,
  1405	                                      lv_color_hex(UI_TEXT_COLOR), 0);
  1406	        }
  1407	      if (g_alert_message != NULL && g_alert_overlay != NULL)
  1408	        {
  1409	          lv_label_set_text(g_alert_message, display->pending_alert);
  1410	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1411	          lv_obj_move_foreground(g_alert_overlay);
  1412	        }
  1413	      display->alert_until_ms = now + 60000;
  1414	      display->alert_active = true;
  1415	      syslog(LOG_INFO,
  1416	             "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
  1417	             (unsigned int)display->page_index, display->detail_active ? 1 : 0,
  1418	             alert_label, display->pending_alert);
  1419	      display->alert_pending = false;
  1420	    }
  1421	  pthread_mutex_unlock(&display->lock);
  1422	
  1423	  if (display->alert_active)
  1424	    {
  1425	      if (now < display->alert_until_ms)
  1426	        {
  1427	          lv_timer_handler();
  1428	          return;
  1429	        }
  1430	
  1431	      display->alert_active = false;
  1432	      syslog(LOG_INFO, "[Display] Alert expired\n");
  1433	      if (g_alert_overlay != NULL)
  1434	        {
  1435	          lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1450	      else
  1451	        {
  1452	          display_render_top(display, &state);
  1453	        }
  1454	      display->last_update_ms = now;
  1455	    }
  1456	
  1457	  lv_timer_handler();
  1458	}
